var profile = config.ModeProfiles[requestedMode];
var sent = adapter.ToDeviceMode(profile, device.Capabilities);
var result = await device.SetModeAsync(sent, cancellationToken);
if (!result.Accepted)
    return Failure("mode rejected", result.Reason);

var actual = await device.GetModeAsync(cancellationToken);
if (actual != sent)
    return Failure("read-back differs", actual.ToString());

return Success(profile.Revision);
